import docx, re
d = docx.Document('output/result.docx')
txt = "\n".join(p.text for p in d.paragraphs)
# Required lead families coverage check
fam = {
 "employment/access": ["Senior Systems Engineer","June 13, 2016","February 16, 2018","mholt","access"],
 "prior work disclosed": ["Exhibit A Prior Inventions","Autonomous Ground Vehicle","RoboNav","MIT License"],
 "PathForge start": ["ground up beginning in 2018","Q3 2018","September 2020","starting point"],
 "whitepaper title/authorship": ["PathForge: Next-Generation Autonomous Navigation","Dr. Marcus Holt, CTO and Co-Founder","July 2022","Public Release / Marketing Technical Paper"],
 "DroneNav/public": ["DroneNav","August 15, 2017","Vasquez","Nakamura","Ferreira"],
 "pre-suit chain": ["March 12, 2024","April 5, 2024","cease-and-desist","$15 million","forensic audit"],
}
for k,v in fam.items():
    miss=[x for x in v if x not in txt]
    print(("OK  " if not miss else "MISS"), k, miss)
# File name citations
for f in ["skyvault-complaint.docx","exhibit-f-forensic-log.xlsx","holt-eciaa-agreement.docx","pathforge-whitepaper-excerpt.docx","meridian-cd-response.docx"]:
    print(f, txt.count(f))
# forbidden attributions check
for bad in ["Holt admitted","Holt stole","established that Meridian copied","Meridian infringed"]:
    if bad in txt: print("!!", bad)
print("--- sections:")
for t in txt.split("\n"):
    if re.match(r'^(I|II|III|IV|V|VI|VII|VIII|IX|X)\.\s', t) or re.match(r'^[ABC]\.\d', t): print("  ", t[:95])
PYEOF",
  "description": "Verify coverage and citations"
}

